// Four exact released no-WHERE GROUP BY frontends; no predicate speed claim.
// Reuse immutable date/UTF8/decoder helpers, not a general SQL parser/native.fls.
#include "../src_fullsql_arade2/iub5_reference.hpp"
#include <map>

struct TgColumn { U id,width;bool nullable;U max_chars; }; // max_chars>0 means UTF8 dictionary.
struct TgProfile { std::string id,sql;std::vector<TgColumn>columns;std::vector<U>key_ids;bool count,ordered; };
static const TgProfile& tg_profile(const std::string&id){
 static const std::vector<TgProfile>profiles={
  {"food1","SELECT \"Food_1\".\"device\" AS \"device\" FROM \"Food_1\" GROUP BY \"Food_1\".\"device\" ORDER BY \"device\" ASC ;\n",{{3,32,false,40}},{3},false,true},
  {"ig1","SELECT \"IGlocations1_1\".\"State\" AS \"State\" FROM \"IGlocations1_1\" GROUP BY \"IGlocations1_1\".\"State\" ORDER BY \"State\" ASC ;\n",{{17,32,false,20}},{17},false,true},
  {"iub1","SELECT \"IUBLibrary_1\".\"Calculation_649925789325832192\" AS \"Calculation_649925789325832192\",   CAST(\"IUBLibrary_1\".\"PubYear\" AS BIGINT) AS \"PubYear\",   \"IUBLibrary_1\".\"Sh\" AS \"Sh\",   SUM(1) AS \"usr:Number of Records:ok\",   CAST(EXTRACT(YEAR FROM \"IUBLibrary_1\".\"DateLastCharged\") AS BIGINT) AS \"yr:DateLastCharged:ok\" FROM \"IUBLibrary_1\" GROUP BY \"IUBLibrary_1\".\"Calculation_649925789325832192\",   \"IUBLibrary_1\".\"PubYear\",   \"IUBLibrary_1\".\"Sh\",   \"yr:DateLastCharged:ok\",   \"PubYear\";\n",{{6,32,false,0},{17,16,false,0},{18,32,false,2},{26,32,false,1}},{26,17,18,6},true,false},
  {"iub4","SELECT \"IUBLibrary_1\".\"Inactive (group)\" AS \"Inactive (group)\",   \"IUBLibrary_1\".\"Inactive\" AS \"Inactive\",   \"IUBLibrary_1\".\"Sh\" AS \"Sh\" FROM \"IUBLibrary_1\" GROUP BY \"IUBLibrary_1\".\"Inactive (group)\",   \"IUBLibrary_1\".\"Inactive\", \"IUBLibrary_1\".\"Sh\";\n",{{9,32,true,8},{18,32,false,2},{25,32,false,8}},{25,9,18},false,false},
 };for(const auto&p:profiles)if(p.id==id)return p;throw std::runtime_error("unsupported exact grouping profile");
}
static const TgColumn&tg_column(const TgProfile&p,U id){for(const auto&c:p.columns)if(c.id==id)return c;throw std::runtime_error("profile key column absent");}
static U tg_bias(const TgColumn&c){return c.width==16?32768U:CODE_BIAS;}
static bool tg_bytes_less(const std::string&a,const std::string&b){return std::lexicographical_compare(a.begin(),a.end(),b.begin(),b.end(),[](char x,char y){return (unsigned char)x<(unsigned char)y;});}
static std::vector<std::string>tg_dictionary(const std::string&dir,const std::string&binding,const TgColumn&c){
 std::ifstream f(dir+"/col"+std::to_string(c.id)+".dict",std::ios::binary);need(bool(f),"group dictionary input");char magic[8],source[40];f.read(magic,8);f.read(source,40);need(bool(f)&&std::string(magic,8)=="BSSTR01\n"&&std::string(source,40)==binding,"group dictionary header/binding");
 U k=rd<U>(f);need(k<=1000000,"group dictionary cardinality");std::vector<std::string>d;d.reserve(k);std::set<std::string>seen;uint64_t total=0;
 for(U i=0;i<k;++i){U bytes=rd<U>(f);need(bytes<=1024&&total+bytes<=64ULL*1024*1024,"group dictionary byte budget");total+=bytes;std::string s(bytes,'\0');f.read(s.data(),bytes);need(bool(f),"group dictionary truncation");utf8_exact(s);size_t chars=0;for(unsigned char b:s)chars+=(b&0xc0)!=0x80;need(chars<=c.max_chars&&seen.insert(s).second,"group dictionary width/injective original strings");d.push_back(std::move(s));}
 need(f.peek()==std::char_traits<char>::eof(),"group dictionary suffix");return d;
}
using TgDictionaries=std::map<U,std::vector<std::string>>;
static TgDictionaries tg_dictionaries(const TgProfile&p,const std::string&dir,const std::string&binding){TgDictionaries d;for(const auto&c:p.columns)if(c.max_chars)d.emplace(c.id,tg_dictionary(dir,binding,c));return d;}
static const TgProfile&tg_bound_profile(const std::string&dir){auto s=sql_file(dir+"/profile.txt");need(!s.empty()&&s.back()=='\n',"group profile newline");s.pop_back();const auto&p=tg_profile(s);need(sql_file(dir+"/query.sql")==p.sql,"exact prepared original group SQL");return p;}
static void tg_metadata(const TgProfile&p,const std::vector<Meta3>&m){need(m.size()==p.columns.size(),"group column count");for(U j=0;j<m.size();++j){const auto&c=p.columns[j];need(m[j].id==c.id&&m[j].width==c.width&&m[j].nullable==U(c.nullable)&&m[j].family==5,"fixed group schema/source domains");}}
static void tg_schema(const TgProfile&p,const Table3&t){tg_metadata(p,t.meta);need(t.cs.size()==t.meta.size(),"group encoded column count");for(const auto&c:t.cs)need(c.root->kind==CHUNKS,"group chunk root");}
static void tg_empty(const TgProfile&p,const std::string&dir,const TgDictionaries&d){std::string meta;for(const auto&c:p.columns){meta+=std::to_string(c.id)+" "+std::to_string(c.width)+" "+std::to_string(c.nullable)+" 5 0\n";need(sql_file(dir+"/col"+std::to_string(c.id)+".u32").empty(),"empty normalized source");need(sql_file(dir+"/col"+std::to_string(c.id)+(c.width==16?".biased.u16":".biased.u32")).empty(),"empty source-width stream");need(sql_file(dir+"/col"+std::to_string(c.id)+".valid.bitmap").empty(),"empty validity");if(c.max_chars)need(d.at(c.id).empty(),"empty original dictionary");}need(sql_file(dir+"/columns.tsv")==meta,"empty declared metadata");}
// All logical source values retain their declared type, never a query answer.
static int64_t tg_source_value(const TgColumn&c,U value,const TgDictionaries&d){
 if(c.max_chars)return sql_code(value,d.at(c.id).size());
 int64_t v=int64_t(value)-int64_t(tg_bias(c));
 if(c.width==16)need(value<=65535&&v>=-32768&&v<=32767,"PubYear SMALLINT domain");
 else need(c.id==6&&v>=IUB_MIN_DAY&&v<=IUB_MAX_DAY,"original finite DATE32 domain");return v;
}
static void tg_source_domains(const TgProfile&p,const std::string&dir,const TgDictionaries&d){auto m=metadata3(dir+"/columns.tsv");tg_metadata(p,m);for(U j=0;j<m.size();++j){auto a=raw(dir,m[j].id);auto v=validity3(dir+"/col"+std::to_string(m[j].id)+".valid.bitmap",m[j].n);need(a.size()==m[j].n,"group raw length");for(U i=0;i<a.size();++i){bool live=valid3(v,i);need(live||a[i]==0,"group raw NULL placeholder");need(live||m[j].nullable,"group original NOT NULL");if(live)(void)tg_source_value(p.columns[j],a[i],d);}std::vector<U>packed;if(m[j].width==16){auto v16=raw_block<uint16_t>(dir+"/col"+std::to_string(m[j].id)+".biased.u16");packed.assign(v16.begin(),v16.end());}else packed=raw_block<U>(dir+"/col"+std::to_string(m[j].id)+".biased.u32");need(packed==a,"every source-width original value equals normalized source in row order");}}
static void tg_verify_domains(const TgProfile&p,const Table3&t,const TgDictionaries&d){for(U j=0;j<t.cs.size();++j){auto a=cache_column<U>(*t.cs[j].root,t.meta[j].n);for(U i=0;i<a.size();++i)if(valid3(t.valid[j],i)){int64_t v=tg_source_value(p.columns[j],a[i],d);if(p.columns[j].id==6&&!p.columns[j].max_chars){auto civil=iub_civil(v);need(iub_days(civil.y,civil.m,civil.d)==v,"original DATE32 exact full roundtrip");}}}}
struct TgKey { std::array<int64_t,4>values{};U nullmask=0;bool operator<(const TgKey&o)const{return nullmask<o.nullmask||(nullmask==o.nullmask&&values<o.values);} };
using TgGroups=std::map<TgKey,SqlWide>;
static TgKey tg_key(const TgProfile&p,const Table3&t,const TgDictionaries&d,U row,const std::vector<U>&values){need(values.size()==p.columns.size(),"group current row width");TgKey key;
 for(U k=0;k<p.key_ids.size();++k){U id=p.key_ids[k],j=bank_column(t,id);const auto&c=tg_column(p,id);if(!valid3(t.valid[j],row)){need(c.nullable,"group key NOT NULL");key.nullmask|=1U<<k;continue;}int64_t v=tg_source_value(c,values[j],d);key.values[k]=(p.id=="iub1"&&id==6)?iub_civil(v).y:v;}
 return key;
}
static bool tg_key_less(const TgProfile&p,const TgDictionaries&d,const TgKey&a,const TgKey&b){for(U k=0;k<p.key_ids.size();++k){bool an=a.nullmask&(1U<<k),bn=b.nullmask&(1U<<k);if(an!=bn)return an; if(an)continue;const auto&c=tg_column(p,p.key_ids[k]);if(c.max_chars){const auto&as=d.at(c.id).at(size_t(a.values[k]));const auto&bs=d.at(c.id).at(size_t(b.values[k]));if(as!=bs)return tg_bytes_less(as,bs);}else if(a.values[k]!=b.values[k])return a.values[k]<b.values[k];}return false;}
static std::string tg_cell(const TgProfile&p,const TgDictionaries&d,const TgKey&key,U k){if(key.nullmask&(1U<<k))return"null";const auto&c=tg_column(p,p.key_ids[k]);return c.max_chars?sql_json(d.at(c.id).at(size_t(key.values[k]))):sql_json(std::to_string(key.values[k]));}
static std::string tg_columns(const TgProfile&p){if(p.id=="food1")return"[{\"name\":\"device\",\"type\":\"VARCHAR\"}]";if(p.id=="ig1")return"[{\"name\":\"State\",\"type\":\"VARCHAR\"}]";if(p.id=="iub4")return"[{\"name\":\"Inactive (group)\",\"type\":\"VARCHAR\"},{\"name\":\"Inactive\",\"type\":\"VARCHAR\"},{\"name\":\"Sh\",\"type\":\"VARCHAR\"}]";return"[{\"name\":\"Calculation_649925789325832192\",\"type\":\"VARCHAR\"},{\"name\":\"PubYear\",\"type\":\"BIGINT\"},{\"name\":\"Sh\",\"type\":\"VARCHAR\"},{\"name\":\"usr:Number of Records:ok\",\"type\":\"HUGEINT\"},{\"name\":\"yr:DateLastCharged:ok\",\"type\":\"BIGINT\"}]";}
static std::string tg_result(const TgProfile&p,const TgDictionaries&d,const TgGroups&groups){std::vector<const TgGroups::value_type*>order;order.reserve(groups.size());for(const auto&entry:groups)order.push_back(&entry);std::sort(order.begin(),order.end(),[&](auto a,auto b){return tg_key_less(p,d,a->first,b->first);});std::string out="{\"columns\":"+tg_columns(p)+",\"rows\":[";bool first=true;for(auto entry:order){if(!first)out+=',';first=false;out+='[';const auto&key=entry->first;for(U k=0;k<p.key_ids.size();++k){if(k)out+=',';if(p.count&&k==3){out+=sql_json(sql_decimal(entry->second));out+=',';}out+=tg_cell(p,d,key,k);}out+=']';}return out+"]}\n";}
static void tg_add(TgGroups&g,const TgKey&key){auto&count=g[key];need(count<1000000,"bounded SUM1 group count");++count;}// row admission n<=1e6, exact signed128 no overflow.
static int tg_selftest(){
 uint64_t date_checks=0;for(int y:{1,4,100,400,1600,1700,1800,1899,1900,1901,1969,1970,2000,2100,2400,9999})for(int m=1;m<=12;++m)for(int day:{1,iub_month_days(y,m)}){auto v=iub_days(y,m,day);auto c=iub_civil(v);need(c.y==y&&c.m==m&&c.d==day,"group Gregorian original date inverse");++date_checks;}
 const auto&p=tg_profile("iub4");TgDictionaries d{{9,{"","A"}},{18,{"x"}},{25,{"g"}}};TgKey a,b;a.nullmask=2;a.values={0,0,0,0};b.values={0,0,0,0};TgGroups groups;tg_add(groups,a);tg_add(groups,b);tg_add(groups,a);need(groups.size()==2&&groups.at(a)==2&&groups.at(b)==1,"NULL identity distinct empty and repeated tuple");need(tg_key_less(p,d,a,b),"unordered canonical NULL first only");auto text=tg_result(p,d,groups);need(text.find("[\"g\",null,\"x\"]")!=std::string::npos&&text.find("[\"g\",\"\",\"x\"]")!=std::string::npos,"typed NULL versus empty export");
 need(tg_bytes_less("e\xcc\x81","\xc3\xa9")&&tg_bytes_less("\xc3\xa9","\xf0\x9f\x98\x80"),"unsigned UTF8 bytes order non-normalized");
 TgKey x,y;x.values={0,-32768,0,1};y.values={0,32767,0,9999};need(x<y,"signed key equality map");const auto&ip=tg_profile("iub1");TgDictionaries id{{18,{"s"}},{26,{"c"}}};TgGroups ig;tg_add(ig,x);tg_add(ig,x);tg_add(ig,y);auto it=tg_result(ip,id,ig);need(it.find("[\"c\",\"-32768\",\"s\",\"2\",\"1\"]")!=std::string::npos&&it.find("[\"c\",\"32767\",\"s\",\"1\",\"9999\"]")!=std::string::npos,"BIGINT keys and exact HUGEINT literal1 positions");
 uint64_t rejects=0;for(U invalid:{0U,CODE_BIAS-1,CODE_BIAS+2}){bool caught=false;try{(void)tg_source_value(tg_column(p,9),invalid,d);}catch(...){caught=true;}need(caught,"dictionary code invalid fixture");++rejects;}bool caught=false;try{(void)tg_source_value(tg_column(ip,17),65536,id);}catch(...){caught=true;}need(caught,"SMALLINT biased overflow fixture");++rejects;
 for(const auto&name:{"food1","ig1","iub1","iub4"}){const auto&pp=tg_profile(name);need(tg_result(pp,{},{}).find("\"rows\":[]")!=std::string::npos,"complete typed empty query result");}
 std::cout<<"{\"group_helpers\":\"PASS\",\"date_inverse_cases\":"<<date_checks<<",\"invalid_domains\":"<<rejects<<",\"profiles\":4,\"observed_values_used\":false,\"predicate_claim\":false}\n";return 0;
}
static int tg_entry(int argc,char**argv){need(argc>=2,"group command");std::string mode=argv[1];if(mode=="selftest_groups"){need(argc==2,"group helper arity");return tg_selftest();}need(mode=="build_groups"||mode=="verify_groups"||mode=="query_groups","group command name");patch_fusion_enabled=true;physical_fill_mode=3;need(compare_mask_available(),"SSE2 availability before frozen kernel");compare_mask_enabled=true;
 if(mode=="build_groups"||mode=="verify_groups"){need(argc==4,"group build/verify arity");bool building=mode=="build_groups";std::string dir=building?argv[2]:argv[3],path=building?argv[3]:argv[2];const auto&p=tg_bound_profile(dir);auto begin=Clock::now();auto binding=binding3(dir+"/binding.txt");auto d=tg_dictionaries(p,dir,binding);bool empty=sql_empty(dir);if(empty){tg_empty(p,dir,d);sql_empty_encoded(path,binding,building);}else{tg_source_domains(p,dir,d);Table3 t=building?construct3(dir):load3(path,binding);tg_schema(p,t);if(building){save3(path,t);t=load3(path,binding);}verify3(t,dir);tg_verify_domains(p,t,d);}std::cout<<"{\"group_build_or_verify_ms\":"<<ms(begin)<<",\"profile\":"<<sql_json(p.id)<<",\"empty_relation\":"<<(empty?"true":"false")<<"}\n";return 0;}
 need(argc==9,"query_groups encoded prepared SQL method result bitmap-or-dash metrics");auto begin=Clock::now();std::string dir=argv[3],method=argv[5];const auto&p=tg_bound_profile(dir);need(sql_file(argv[4])==p.sql,"only unchanged exact original grouping SQL");need(method=="decoded_blocks"||method=="paid_cache"||method=="packed_source","group execution schedule");auto binding=binding3(dir+"/binding.txt");auto d=tg_dictionaries(p,dir,binding);bool empty=sql_empty(dir),diagnostic=std::string(argv[7])!="-";Table3 t;std::vector<std::vector<U>>plain;U n=0;
 if(empty){tg_empty(p,dir,d);sql_empty_encoded(argv[2],binding,false);}else if(method=="packed_source"){t.binding=binding;t.meta=metadata3(dir+"/columns.tsv");tg_metadata(p,t.meta);n=t.meta[0].n;for(const auto&c:p.columns){std::string prefix=dir+"/col"+std::to_string(c.id);std::vector<U>a;if(c.width==16){auto v=raw_block<uint16_t>(prefix+".biased.u16");a.assign(v.begin(),v.end());}else a=raw_block<U>(prefix+".biased.u32");need(a.size()==n,"true source-width packed length");auto valid=validity3(prefix+".valid.bitmap",n);for(U i=0;i<n;++i){bool live=valid3(valid,i);need(live||a[i]==0,"source-width packed canonical NULL");need(live||c.nullable,"source-width packed original NOT NULL");}plain.push_back(std::move(a));t.valid.push_back(std::move(valid));}}
 else{t=load3(argv[2],binding);tg_schema(p,t);n=t.meta[0].n;}double setup_ms=ms(begin);auto query=Clock::now();TgGroups groups;B diag;if(diagnostic)diag.assign((size_t(n)+63)/64,0);std::vector<U>values(p.columns.size());uint64_t blocks=0;double cold_decode_ms=0;auto consume=[&](U row){tg_add(groups,tg_key(p,t,d,row,values));if(diagnostic)bit(diag,row,true);};
 if(n&&method=="decoded_blocks"){std::vector<Scratch>scratch(p.columns.size());for(U off=0;off<n;off+=V){U take=std::min(V,n-off);for(U j=0;j<t.cs.size();++j){decode_bulk(*t.cs[j].root->children[off/V],scratch[j]);++blocks;}for(U i=0;i<take;++i){for(U j=0;j<values.size();++j)values[j]=scratch[j].d[i];consume(off+i);}}}
 else if(n){if(method=="paid_cache"){auto cold=Clock::now();for(const auto&c:t.cs)plain.push_back(cache_column<U>(*c.root,n));cold_decode_ms=ms(cold);blocks=p.columns.size()*((n+V-1)/V);}for(U row=0;row<n;++row){for(U j=0;j<values.size();++j)values[j]=plain[j][row];consume(row);}}
 auto result=tg_result(p,d,groups);double query_ms=ms(query);auto rss=resident_kib();auto output_start=Clock::now();std::ofstream output(argv[6],std::ios::binary);output.write(result.data(),result.size());output.flush();need(bool(output),"complete grouping typed output");output.close();need(bool(output),"complete grouping output close");if(diagnostic){std::ofstream bitmap(argv[7],std::ios::binary);bitmap.write(reinterpret_cast<const char*>(diag.data()),diag.size()*8);bitmap.flush();need(bool(bitmap),"complete grouping allrow diagnostic bitmap");bitmap.close();need(bool(bitmap),"complete grouping diagnostic close");}double output_ms=ms(output_start);uint64_t cache_bytes=0,dict_bytes=0,dict_capacity=0;for(const auto&a:plain)cache_bytes+=a.capacity()*sizeof(U);for(const auto&entry:d){dict_capacity+=entry.second.capacity()*sizeof(std::string);for(const auto&s:entry.second){dict_bytes+=s.size();dict_capacity+=s.capacity();}}
 std::ofstream metrics(argv[8]);metrics<<"{\"profile\":"<<sql_json(p.id)<<",\"method\":"<<sql_json(method)<<",\"rows\":"<<n<<",\"groups\":"<<groups.size()<<",\"setup_ms\":"<<setup_ms<<",\"query_ms\":"<<query_ms<<",\"cold_decode_once_ms\":"<<cold_decode_ms<<",\"output_write_ms\":"<<output_ms<<",\"decoded_blocks\":"<<blocks<<",\"predicate_count\":0,\"predicate_bank_bytes\":0,\"diagnostic_allrows_bitmap_bytes\":"<<diag.size()*8<<",\"result_bytes\":"<<result.size()<<",\"original_dictionary_utf8_bytes\":"<<dict_bytes<<",\"dictionary_capacity_nominal_bytes\":"<<dict_capacity<<",\"group_key_count_nominal_payload_bytes\":"<<groups.size()*sizeof(TgGroups::value_type)<<",\"tree_allocator_node_overhead_not_measured\":true,\"decoded_cache_capacity_bytes\":"<<cache_bytes<<",\"decoder_scratch_nominal_bytes\":"<<(n&&method!="packed_source"?(method=="paid_cache"?1:p.columns.size())*sizeof(Scratch):0)<<",\"packed_u16_expansion_charged_in_setup\":true,\"whole_process_rss_kib\":"<<rss<<",\"compressed_tree_retained\":"<<((empty||method=="packed_source")?"false":"true")<<",\"unfiltered_grouping_coverage_only\":true,\"full_result_serialization_charged\":true,\"no_timing_claim\":true}\n";metrics.flush();need(bool(metrics),"group metric flush");return 0;
}
int main(int argc,char**argv){try{return tg_entry(argc,argv);}catch(const std::exception&e){std::cerr<<"REJECT: "<<e.what()<<'\n';return 2;}}
